mapper.select:
select a.num, a.title, a.content, a.writer, a.image_filename as imageFilename, a.download_filename as downloadFilename, 
m.profile, m.name as writerName
from article a join member m on(a.writer=m.id) 
where a.num=#{num}

mapper.update:
update article 
	set title=#{title}, 
	content=#{content}

		, image_filename=#{imageFilename}


		, download_filename=#{downloadFilename}

where num=#{num}
